import jsPDF from 'jspdf';

export const generateProcedurePDF = (procedure) => {
  try {
    // Create new PDF document
    const pdf = new jsPDF();
    let yPosition = 25;
    const pageWidth = pdf.internal.pageSize.width;
    const margin = 20;
    const contentWidth = pageWidth - (margin * 2);

    // Helper function to add text with word wrapping and larger fonts
    const addText = (text, fontSize = 14, isBold = false, indent = 0) => {
      pdf.setFontSize(fontSize);
      pdf.setTextColor(0, 0, 0); // Always black text
      
      if (isBold) {
        pdf.setFont(undefined, 'bold');
      } else {
        pdf.setFont(undefined, 'normal');
      }

      const availableWidth = contentWidth - indent;
      const lines = pdf.splitTextToSize(text, availableWidth);
      
      // Check if we need a new page
      if (yPosition + (lines.length * fontSize * 0.6) > pdf.internal.pageSize.height - 30) {
        pdf.addPage();
        yPosition = 25;
      }
      
      pdf.text(lines, margin + indent, yPosition);
      yPosition += lines.length * fontSize * 0.6 + 4;
    };

    // Helper function to add section header with emphasis
    const addSectionHeader = (title, fontSize = 16) => {
      addSpace(8);
      addText(`━━━ ${title.toUpperCase()} ━━━`, fontSize, true);
      addSpace(5);
    };

    // Helper function to add numbered list (like the app uses)
    const addNumberedList = (items, fontSize = 13, sectionColor = 'default') => {
      if (!items || items.length === 0) return;
      
      items.forEach((item, index) => {
        // Clean up the item text (remove existing bullets/numbers)
        const cleanItem = item.replace(/^[•·\-0-9\.)\s]*/, '').trim();
        // Add numbered format like the app: "1. Item text"
        addText(`${index + 1}. ${cleanItem}`, fontSize, false, 10);
      });
    };

    // Helper function to add bulleted list with proper formatting
    const addBulletList = (items, fontSize = 13) => {
      if (!items || items.length === 0) return;
      
      items.forEach((item) => {
        // Clean up the item text (remove existing bullets)
        const cleanItem = item.replace(/^[•·-]\s*/, '').trim();
        addText(`• ${cleanItem}`, fontSize, false, 10);
      });
    };

    // Helper function to add spacing
    const addSpace = (space = 12) => {
      yPosition += space;
    };

    // Practice Header with Logo/Branding
    if (procedure.practiceName) {
      addText(procedure.practiceName, 20, true);
      if (procedure.practiceAddress) {
        addText(procedure.practiceAddress, 12);
      }
      if (procedure.practicePhone) {
        addText(`Phone: ${procedure.practicePhone}`, 12);
      }
      if (procedure.practiceWebsite) {
        addText(procedure.practiceWebsite, 12);
      }
      addSpace(20);
    }

    // Header - Clean and simple with larger fonts
    addText('Post-Operative Care Guide', 22, true);
    addText(procedure.name, 18, true);
    
    // Check if this is a patient-specific assignment or general library procedure
    const isPatientAssignment = procedure.patientName && procedure.performedDate;
    
    if (isPatientAssignment) {
      addSpace(20);
      // Assignment Information Section (only for patient assignments)
      addText('Assignment Information', 18, true);
      addSpace(8);
      
      addText('Patient Details', 16, true);
      addText(`Patient: ${procedure.patientName}`, 13);
      if (procedure.patientEmail) {
        addText(`Email: ${procedure.patientEmail}`, 13);
      }
      addSpace(12);
      
      addText('Treatment Details', 16, true);
      addText(`Performed: ${procedure.performedDate}`, 13);
      if (procedure.followUpDate) {
        addText(`Follow-up: ${procedure.followUpDate}`, 13);
      }
      if (procedure.dentistName) {
        addText(`Dentist: ${procedure.dentistName}`, 13);
      }
      addText(`Status: ${procedure.status || 'active'}`, 13);
      addSpace(18);

      // Practice Notes Section (only for patient assignments)
      if (procedure.practiceNotes) {
        addText('Practice Notes', 18, true);
        addSpace(5);
        addText(procedure.practiceNotes, 13);
        addSpace(18);
      }

      // Custom Instructions Section (only for patient assignments)
      if (procedure.customInstructions && procedure.customInstructions.length > 0) {
        addText('Custom Instructions', 18, true);
        addSpace(5);
        addText(procedure.customInstructions, 13);
        addSpace(18);
      }
    } else {
      // For library procedures, just add some spacing and specialty info
      if (procedure.specialtyName) {
        addText(`Specialty: ${procedure.specialtyName}`, 14);
      }
      if (procedure.duration) {
        addText(`Typical Recovery: ${procedure.duration}`, 14);
      }
      addSpace(20);
    }

    // Post-Operative Care Instructions Section
    addText('Post-Operative Care Instructions', 18, true);
    addSpace(12);
    
    // Overview - Parse exactly like the app does
    if (procedure.overview) {
      addSectionHeader('Overview');
      
      // Parse overview exactly like ProcedurePage.jsx does
      const lines = procedure.overview.split('\n');
      lines.forEach((line) => {
        const trimmedLine = line.trim();
        
        // Handle empty lines - create spacing
        if (trimmedLine === '') {
          addSpace(4);
          return;
        }
        
        // Handle bullet points
        if (trimmedLine.startsWith('•') || trimmedLine.startsWith('-')) {
          const bulletText = trimmedLine.replace(/^[•-]\s*/, '');
          addText(`• ${bulletText}`, 13, false, 10);
          return;
        }
        
        // Handle markdown-style headers (**text**)
        if (trimmedLine.includes('**')) {
          // If it's a complete header (starts and ends with **)
          if (trimmedLine.startsWith('**') && trimmedLine.endsWith('**') && trimmedLine.length > 4) {
            const headerText = trimmedLine.replace(/\*\*/g, '');
            addText(headerText, 14, true);
            addSpace(4);
            return;
          }
          // Handle mixed content with headers inline - convert ** to bold styling
          else {
            const parts = trimmedLine.split(/(\*\*[^*]+\*\*)/);
            let formattedText = '';
            parts.forEach(part => {
              if (part.startsWith('**') && part.endsWith('**')) {
                // In PDF, we'll use uppercase for emphasis since we can't mix bold/normal in same line easily
                formattedText += part.replace(/\*\*/g, '').toUpperCase();
              } else {
                formattedText += part;
              }
            });
            addText(formattedText, 13);
            return;
          }
        }
        
        // Regular paragraphs
        if (trimmedLine.length > 0) {
          addText(trimmedLine, 13);
          addSpace(4);
        }
      });
      
      addSpace(15);
    }
    
    // Emergency Alert (like the app's red alert box)
    addText('🚨 EMERGENCY ALERT 🚨', 16, true);
    addSpace(3);
    addText('Emergency: If you experience severe bleeding, difficulty breathing, or signs of severe allergic reaction, call 911 IMMEDIATELY.', 13, true);
    addSpace(18);
    
    // Immediate Aftercare with numbered list (like the app)
    if (procedure.immediateAftercare && procedure.immediateAftercare.length > 0) {
      addSectionHeader('Immediate Aftercare');
      addNumberedList(procedure.immediateAftercare, 13, 'green');
      addSpace(15);
    }

    // Diet Restrictions with numbered list (like the app)
    if (procedure.dietRestrictions && procedure.dietRestrictions.length > 0) {
      addSectionHeader('Diet Restrictions');
      addNumberedList(procedure.dietRestrictions, 13, 'orange');
      addSpace(15);
    }

    // Warning Signs with special formatting (like the app's red section)
    if (procedure.warningSignsToCallDoctor && procedure.warningSignsToCallDoctor.length > 0) {
      addSpace(8);
      addText('⚠️ WARNING SIGNS - CALL YOUR DENTIST IMMEDIATELY ⚠️', 16, true);
      addSpace(3);
      addText('Contact your dental office immediately if you experience any of the following:', 13, true);
      addSpace(5);
      
      // Use special warning bullets
      procedure.warningSignsToCallDoctor.forEach((sign) => {
        const cleanSign = sign.replace(/^[•·-]\s*/, '').trim();
        addText(`⚠️ ${cleanSign}`, 13, false, 10);
      });
      addSpace(15);
    }

    // Recovery Timeline with better formatting (like the app's day badges)
    if (procedure.recoveryTimeline && procedure.recoveryTimeline.length > 0) {
      addSectionHeader('Recovery Timeline');
      procedure.recoveryTimeline.forEach((timeline) => {
        // Format like "Day 1-3: Activity description" with emphasis on day
        addText(`DAY ${timeline.day}: ${timeline.activity}`, 13, false, 10);
      });
      addSpace(15);
    }

    // Medications with pill icons (like the app)
    if (procedure.medications && procedure.medications.length > 0) {
      addSectionHeader('Medications');
      procedure.medications.forEach((medication) => {
        const cleanMed = medication.replace(/^[•·-]\s*/, '').trim();
        addText(`💊 ${cleanMed}`, 13, false, 10);
      });
      addSpace(20);
    }

    // Contact Information - Clean footer with practice info
    addText('Contact Information', 16, true);
    addSpace(5);
    if (procedure.practiceName) {
      addText(`Practice: ${procedure.practiceName}`, 13);
    }
    if (procedure.practicePhone) {
      addText(`Phone: ${procedure.practicePhone}`, 13);
    }
    addText('For emergencies, contact your dentist immediately or call 911.', 13, true);

    // Save the PDF with clean filename
    const procedureName = procedure.name || 'procedure';
    const patientPart = procedure.patientName ? `_${procedure.patientName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}` : '';
    const fileName = `${procedureName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}${patientPart}_postop_care.pdf`;
    pdf.save(fileName);
    
    return true;
  } catch (error) {
    console.error('Error generating PDF:', error);
    return false;
  }
};